<?php require dirname(__DIR__,2).'/app/bootstrap.php';Auth::requireLogin();require_post();verify_csrf();$id=(int)($_POST['transcript_id']??0);$s=db()->prepare("SELECT transcript_text FROM transcripts WHERE id=? AND user_id=? AND status='completed'");$s->execute([$id,Auth::id()]);$t=$s->fetch();if(!$t){flash('danger','Transcript not found.');redirect('history.php');}try{$out=AIService::run($_POST['task']??'',(string)$t['transcript_text'],substr($_POST['language']??'English',0,40));db()->prepare('INSERT INTO ai_outputs(user_id,transcript_id,task,output_text,created_at) VALUES(?,?,?,?,NOW())')->execute([Auth::id(),$id,$_POST['task'],$out]);$oid=(int)db()->lastInsertId();redirect('ai-output.php?id='.$oid);}catch(Throwable $e){flash('danger',$e->getMessage());redirect('transcript.php?id='.$id);}
